$saved=query($db,'SELECT email,course,institution,level,whatsapp,calling_line,state_origin,times_attended FROM natcon_delegates WHERE reference=? ORDER BY id LIMIT 1',[$o['reference']])->fetch();check($saved['email']==='one@example.test'&&$saved['course']==='Islamic Studies'&&$saved['institution']==='Test University'&&$saved['level']==='Graduate'&&$saved['whatsapp']==='08000000000'&&$saved['state_origin']==='Osun'&&(int)$saved['times_attended']===2,'Requested delegate profile persists');check(query($db,'SELECT phone FROM natcon_delegates WHERE reference=? ORDER BY id LIMIT 1',[$o['reference']])->fetchColumn()==='08000000000','Legacy phone field remains compatible');
